static String formattedQuery(String email) {
    return """
            SELECT id, name
            FROM customer
            WHERE email = '%s'
            """.formatted(email);
}

static final String BY_EMAIL = """
        SELECT id, name
        FROM customer
        WHERE email = ?
        """;

static void bound(Connection conn, String email) throws SQLException {
    try (PreparedStatement ps = conn.prepareStatement(BY_EMAIL)) {
        ps.setString(1, email);
        ps.executeQuery();
    }
}

static final String EXPECTED = """
        {
          "id": 42,
          "email": "contact@example.com"
        }
        """;

static boolean sameLines(String a, String b) {
    return a.lines().toList().equals(b.lines().toList());
}

static String escape(String text) {
    return text.replace("&", "&amp;")          // first, or it would re-escape the ones below
               .replace("<", "&lt;")
               .replace(">", "&gt;")
               .replace("\"", "&quot;")
               .replace("'", "&#39;");
}

static final String LOG_LINE = """
        (?<level>WARN|ERROR) \\s+         # severity
        order=(?<order>\\d{4}-\\d{6}) \\s+   # year-sequence
        took=(?<ms>\\d+)ms                # duration
        """;

